<script setup>
import {computed,ref} from 'vue'
import {sourceRecords} from './sourceRecords'
const section=ref('证据地图'),country=ref('泰国'),owner=ref('业务负责人'),checks=ref([]),cost=ref(null),quote=ref(null),logistics=ref(null),tax=ref(null),tasks=ref([])
const requirements=[{id:'product',name:'具体产品及规格',why:'用于匹配商品范围与技术要求',role:'产品负责人'},{id:'route',name:'发货地与制造地',why:'区分物流路线和原产资格',role:'供应商'},{id:'date',name:'预计进口月份',why:'确定需要核验的政策版本',role:'业务负责人'},{id:'origin',name:'本批原产证明',why:'用于核验优惠申请条件，不代表自动享惠',role:'供应商'},{id:'price',name:'同口径渠道报价',why:'支持成本比较和试单讨论',role:'当地渠道'}]
const missing=computed(()=>requirements.filter(r=>!checks.value.includes(r.id)))
const coverage=computed(()=>['泰国','印度尼西亚','越南'].map(name=>{const rows=sourceRecords.filter(r=>r.country===name);return {name,market:rows.filter(r=>r.kind==='市场数据').length,policy:rows.filter(r=>r.kind==='政策公告').length,reviewed:rows.filter(r=>r.reviewStatus==='已人工复核').length,total:rows.length}}))
const delta=computed(()=>[cost.value,quote.value,logistics.value,tax.value].every(v=>v!==null&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0)?Number(quote.value)-Number(cost.value)-Number(logistics.value)-Number(tax.value):null)
function addTask(title,role,source='用户准备清单'){if(tasks.value.some(t=>t.title===title))return;tasks.value.push({id:Date.now()+Math.random(),title,owner:role,source,done:false})}
function exportPack(){const data={type:'决策准备记录，不是合规结论',createdAt:new Date().toISOString(),country:country.value,industry:'新能源汽车',materialsProvided:checks.value,missing:missing.value.map(r=>r.name),scenario:{currency:'THB/辆',productCost:cost.value,channelQuote:quote.value,logistics:logistics.value,tax:tax.value,difference:delta.value},sourceIds:sourceRecords.filter(s=>s.country===country.value).map(s=>s.id),tasks:tasks.value};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='decision-workspace.json';a.click();URL.revokeObjectURL(url)}
</script>
<template><main class="decision-lab"><div class="lab-heading"><div><p class="eyebrow">DECISION LAB / 从信息到行动</p><h1>先看清依据，再决定下一步。</h1><p class="intro">证据、业务条件、成本情景与协作任务，在同一份决策记录里连接。</p></div><button class="primary" @click="exportPack">导出决策记录 ↓</button></div><div class="lab-navigation"><button v-for="s in ['证据地图','材料准备','政策时间线','报价试算','行动看板']" :class="{selected:section===s}" @click="section=s">{{s}}</button></div>
<section v-if="section==='证据地图'"><h2>比较的是资料覆盖，不是投资排名</h2><div class="lab-country-grid"><article class="panel" v-for="c in coverage"><small>新能源汽车 / {{c.name}}</small><h2>{{c.total ? c.total+' 条来源记录':'尚无收录'}}</h2><dl><dt>市场数据</dt><dd>{{c.market}} 条</dd><dt>政策公告</dt><dd>{{c.policy}} 条</dd><dt>人工复核完成</dt><dd>{{c.reviewed}} 条</dd></dl><p class="lab-muted">{{c.total?'现有记录仍需人工复核及个案适用核验。':'缺少资料，不意味着没有壁垒或投资风险。'}}</p><button class="text-button" @click="country=c.name;section='材料准备'">为该市场准备资料 →</button></article></div><h3>决策前还缺哪些维度？</h3><div class="lab-dimensions"><span v-for="d in ['细分商品税则：未接入','强制认证实施依据：未接入','渠道采购价：企业提供','企业原产材料：企业提供']">{{d}}</span></div></section>
<section v-else-if="section==='材料准备'"><div class="toolbar"><el-select v-model="country"><el-option v-for="c in ['泰国','印度尼西亚','越南']" :value="c" :label="c"/></el-select></div><h2>材料准备 {{checks.length}} / {{requirements.length}}</h2><p class="lab-muted">勾选表示企业自述已准备，不代表材料已审核或符合政策。</p><div class="panel"><label class="material-row" v-for="r in requirements"><input type="checkbox" :value="r.id" v-model="checks"><div><strong>{{r.name}}</strong><p>{{r.why}}</p></div><small>{{r.role}}</small></label></div><h3>下一步可以交给谁？</h3><div class="lab-task" v-for="r in missing"><span>{{r.name}}</span><button class="text-button" @click="addTask('补充'+r.name,r.role)">{{tasks.some(t=>t.title==='补充'+r.name)?'已加入行动看板':'加入行动看板 +'}}</button></div><p v-if="!missing.length">准备项已勾选齐全，下一步是核对真实性与适用性，而不是直接判定合规。</p></section>
<section v-else-if="section==='政策时间线'"><h2>同一政策名称，不同适用窗口</h2><p class="lab-muted">基于已收录快照的时间轴，不是自动监测服务；后续公告不必然替代整份旧政策。</p><article class="panel lab-timeline" v-for="r in sourceRecords.filter(s=>s.kind==='政策公告').slice().sort((a,b)=>a.published.localeCompare(b.published))"><small>{{r.published}} · {{r.publisher}}</small><h3>{{r.title}}</h3><p>{{r.period}}</p><p>{{r.impact}}</p><div class="lab-source-actions"><a :href="r.url" target="_blank" rel="noopener noreferrer">核对官方原文 ↗</a><button class="text-button" @click="addTask('核查：'+r.title,'研究分析员',r.id)">{{tasks.some(t=>t.source===r.id)?'已创建核查任务':'创建核查任务 +'}}</button></div></article></section>
<section v-else-if="section==='报价试算'"><h2>改变一个假设，观察价格空间</h2><p class="lab-muted">同一币种、同一配置、同一交货口径下的用户情景试算；不自动填税率，不表示利润或正式报价。</p><div class="two-col"><div class="panel"><label v-for="field in []"/><!-- all inputs intentionally start empty -->
<label>产品成本（THB / 辆）</label><el-input-number v-model="cost" :min="0" :max="100000000" :precision="2"/><label>物流费用（THB / 辆）</label><el-input-number v-model="logistics" :min="0" :max="100000000" :precision="2"/><label>已核算税费或假设税费（THB / 辆）</label><el-input-number v-model="tax" :min="0" :max="100000000" :precision="2"/><label>同口径渠道采购报价（THB / 辆）</label><el-input-number v-model="quote" :min="0" :max="100000000" :precision="2"/></div><div class="panel"><small>报价 − 产品成本 − 物流 − 税费</small><h2 class="scenario-value">{{delta===null?'等待填写':delta.toLocaleString('zh-CN',{maximumFractionDigits:2})+' THB / 辆'}}</h2><p>{{delta===null?'缺项不会按零计算，确认为零时请明确填写 0。':delta<0?'当前输入下差额为负，需重新核对成本、报价与条件。':'当前输入下存在正差额，仍需扣除未计入的费用并核对交易条件。'}}</p><p class="lab-muted">未覆盖售后、融资、渠道佣金等费用；金额均来自用户输入，无官方税费计算承诺。</p><button class="text-button" @click="addTask('核对报价口径及税费明细','业务负责人','用户情景试算')">创建报价复核任务 +</button></div></div></section>
<section v-else><h2>让待核验事项有负责人</h2><p class="lab-muted">本次会话的任务板，退出或刷新后不保留；可先导出决策记录。</p><p v-if="!tasks.length">还没有任务。可从材料准备、时间线或报价试算中创建。</p><article class="panel lab-task-card" v-for="t in tasks" :key="t.id"><label><input type="checkbox" v-model="t.done"> {{t.title}}</label><el-select v-model="t.owner" aria-label="任务负责人"><el-option v-for="r in ['业务负责人','研究分析员','产品负责人','供应商','当地渠道']" :value="r" :label="r"/></el-select><small>依据：{{t.source}} · {{t.done?'任务已处理（不等于政策已核验）':'待处理'}}</small></article></section></main></template>
<style>.decision-lab{max-width:1250px;margin:auto;padding:30px}.lab-heading{display:flex;align-items:center;justify-content:space-between;gap:24px}.lab-navigation{display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #ddd;padding:15px 0;margin-bottom:30px}.lab-navigation button{border:0;padding:11px 19px;border-radius:25px;background:#f5f6f7;font-size:13px;color:#606b73}.lab-navigation .selected{background:#202124;color:white}.lab-country-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.lab-country-grid h2{margin:20px 0}.lab-muted{font-size:12px;color:#78848c;line-height:1.9}.lab-dimensions{display:flex;gap:12px;flex-wrap:wrap}.lab-dimensions span{background:#f4f7f8;padding:12px;border-radius:9px;font-size:12px}.material-row{display:flex;gap:18px;align-items:center;padding:15px 0;border-bottom:1px solid #eee}.material-row div{flex:1}.material-row strong{font-size:14px}.material-row p{font-size:12px;color:#7d8992;margin:5px 0}.lab-task,.lab-source-actions{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:14px 0;border-bottom:1px solid #eee;font-size:13px}.lab-timeline{margin:15px 0;border-left:3px solid #20a7d4}.lab-timeline p{font-size:13px}.lab-source-actions a{color:#168bb3}.decision-lab .panel>label{display:block;margin:17px 0 9px;font-size:13px}.decision-lab .panel>label.material-row{display:flex}.scenario-value{font-size:30px;margin:35px 0}.lab-task-card{margin:12px 0}.lab-task-card .el-select{max-width:210px;display:block;margin:14px 0}@media(max-width:700px){.decision-lab{padding:20px}.lab-country-grid{grid-template-columns:1fr}.lab-heading{display:block}.lab-navigation{gap:7px}.lab-navigation button{padding:9px 12px}.material-row{flex-wrap:wrap}.lab-source-actions{align-items:flex-start;flex-direction:column}.scenario-value{font-size:24px}}
</style>
